require_once __DIR__.'/core.php';tt_require_login();$db=tt_db_open(true);$user=(string)$_SESSION['name'];$a=$user.';%';$b='%;'.$user.';%';$c='%;'.$user;$s=tt_prepare($db,"SELECT `id`,`title`,`content`,`dt`,`tags`,`name`,`recipients`,`file` FROM `posts` WHERE `type`='message' AND (`name`=? OR `recipients`=? OR `recipients` LIKE ? OR `recipients` LIKE ? OR `recipients` LIKE ?) ORDER BY `dt` DESC,`id` DESC LIMIT 150");$s->bind_param('sssss',$user,$user,$a,$b,$c);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$db->close();
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Messages</title></head><body><?php tt_nav('messages.php');?><main class="content"><div class="actions"><a href="create.php">New message</a></div><h2>Messages</h2><section class="grid"><?php foreach($rows as $r):?><article class="card"><h3><?=tt_h($r['title'])?></h3><p class="meta">From <?=tt_h($r['name'])?> · to <?=tt_h($r['recipients'])?> · <?=tt_h($r['dt'])?></p><p><?=nl2br(tt_h($r['content']))?></p><?php if($r['file']!==''):?><p><a href="<?=tt_h($r['file'])?>">Attachment</a></p><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><article class="card"><p>No messages yet.</p></article><?php endif;?></section></main></body></html>